{"command":"python3 - <<'PY'
import csv
input_path='outputs/t11_city_indicator_matrix.csv'

reader=open(input_path,'r',newline='')
reader=csv.DictReader(reader)
indicators=list(reader.fieldnames[3:])
rows=list(reader)
total=len(rows)
missing_counts={}
for row in rows:
    for ind in indicators:
        if row[ind]=='' or row[ind] is None:
            missing_counts[ind]=missing_counts.get(ind,0)+1
print('total rows',total)
print('indicators',indicators)
for ind in indicators:
    print(ind, missing_counts.get(ind,0), missing_counts.get(ind,0)/total)
PY"}
